/**
 * danish-eq Dashboard — Main JavaScript
 *
 * Reads data from JSON files generated by the pipeline:
 * - data/signals.json      (today's picks)
 * - data/candidates.json   (scanner output)
 * - data/portfolio.json    (positions + balances)
 * - data/history.json      (completed trades)
 * - data/universe.json     (instrument list)
 */

// ═══════════════════════════════════════════════════════════
// DATA LAYER
// ═══════════════════════════════════════════════════════════

const DATA_BASE = 'data/';

async function loadJSON(filename) {
    try {
        const resp = await fetch(`${DATA_BASE}${filename}`);
        if (!resp.ok) return null;
        return await resp.json();
    } catch (e) {
        console.warn(`Failed to load ${filename}:`, e.message);
        return null;
    }
}

// ═══════════════════════════════════════════════════════════
// TAB NAVIGATION
// ═══════════════════════════════════════════════════════════

function initTabs() {
    const tabs = document.querySelectorAll('.tab');
    const contents = document.querySelectorAll('.tab-content');

    tabs.forEach(tab => {
        tab.addEventListener('click', () => {
            tabs.forEach(t => { t.classList.remove('active'); t.setAttribute('aria-selected', 'false'); });
            contents.forEach(c => c.classList.remove('active'));

            tab.classList.add('active');
            tab.setAttribute('aria-selected', 'true');
            const target = document.getElementById(`tab-${tab.dataset.tab}`);
            if (target) target.classList.add('active');
        });
    });
}

// ═══════════════════════════════════════════════════════════
// SIGNALS TAB
// ═══════════════════════════════════════════════════════════

function renderSignals(signals) {
    const grid = document.getElementById('signalsGrid');
    if (!signals || signals.length === 0) {
        grid.innerHTML = '<div class="empty-state"><p>No signals yet. Pipeline runs at 21:30 UTC (after US close).</p></div>';
        return;
    }

    // Update meta
    document.getElementById('signalCount').textContent = `${signals.length} picks`;
    const avgConf = (signals.reduce((s, p) => s + (p.confidence || 0), 0) / signals.length).toFixed(1);
    document.getElementById('avgConfidence').textContent = `Avg confidence: ${avgConf}/10`;

    grid.innerHTML = signals.map((pick, idx) => {
        const entry = pick.entry_price || 0;
        const target = pick.target_price || 0;
        const sl = pick.stop_loss_price || 0;
        const risk = entry - sl;
        const rr = risk > 0 ? ((target - entry) / risk).toFixed(1) : '—';
        const conf = pick.confidence || 0;
        const confClass = conf >= 7 ? 'confidence-high' : conf >= 5 ? 'confidence-medium' : 'confidence-low';

        return `
            <div class="signal-card" data-index="${idx}">
                <div class="signal-card-header">
                    <span class="signal-symbol">${pick.symbol}</span>
                    <span class="signal-confidence ${confClass}">${conf}/10</span>
                </div>
                <div class="signal-levels">
                    <div class="level-item">
                        <div class="level-label">Entry</div>
                        <div class="level-value entry">${entry.toFixed(2)}</div>
                    </div>
                    <div class="level-item">
                        <div class="level-label">Target</div>
                        <div class="level-value target">${target.toFixed(2)}</div>
                    </div>
                    <div class="level-item">
                        <div class="level-label">Stop Loss</div>
                        <div class="level-value stoploss">${sl.toFixed(2)}</div>
                    </div>
                </div>
                <div class="signal-rationale-preview">${pick.rationale || 'No rationale provided'}</div>
                <div class="signal-meta">
                    <span class="signal-rr">R:R ${rr}</span>
                    <span>Hold: ${pick.holding_days_estimate || '?'}d</span>
                    <button class="btn-rationale" onclick="showRationale(${idx})">🧠 Full Analysis</button>
                </div>
            </div>
        `;
    }).join('');
}

function showRationale(index) {
    const panel = document.getElementById('rationalePanel');
    const signals = window._currentSignals || [];
    const pick = signals[index];
    if (!pick) return;

    document.getElementById('rationaleSymbol').textContent = pick.symbol;

    const entry = pick.entry_price || 0;
    const target = pick.target_price || 0;
    const sl = pick.stop_loss_price || 0;
    const risk = entry - sl;
    const rr = risk > 0 ? ((target - entry) / risk).toFixed(2) : '—';
    const upside = entry > 0 ? (((target - entry) / entry) * 100).toFixed(1) : '—';
    const downside = entry > 0 ? (((entry - sl) / entry) * 100).toFixed(1) : '—';

    document.getElementById('rationaleBody').innerHTML = `
        <div class="rationale-section">
            <div class="rationale-label">AI Rationale</div>
            <p>${pick.rationale || 'No detailed rationale available.'}</p>
        </div>
        <div class="rationale-section">
            <div class="rationale-label">Trade Setup</div>
            <p>
                <strong>Entry:</strong> ${entry.toFixed(2)} →
                <strong>Target:</strong> ${target.toFixed(2)} (+${upside}%) →
                <strong>Stop:</strong> ${sl.toFixed(2)} (-${downside}%)
            </p>
            <p><strong>Risk:Reward:</strong> 1:${rr}</p>
            <p><strong>Holding Period:</strong> ${pick.holding_days_estimate || '5-15'} trading days</p>
            <p><strong>Confidence:</strong> ${pick.confidence}/10</p>
        </div>
        <div class="rationale-section">
            <div class="rationale-label">Position Sizing (ASK)</div>
            <p>
                Target position: per profile (Rs.50K\u20132L for swing)<br>
                Shares: calculated per profile capital<br>
                Max risk per trade: ${downside}% of position value
            </p>
        </div>
        <div class="rationale-section">
            <div class="rationale-label">Scanner Signals</div>
            <p>${pick.scanner_rationale || pick.rationale || 'Passed RS-First v3 scoring with min threshold 7.'}</p>
        </div>
    `;

    panel.style.display = 'block';
    panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

// ═══════════════════════════════════════════════════════════
// PORTFOLIO TAB
// ═══════════════════════════════════════════════════════════

function renderPortfolio(portfolio) {
    if (!portfolio) return;

    const fmt = (v, prefix = '\u20b9') => `${prefix}${(v || 0).toLocaleString('en-IN', { minimumFractionDigits: 0 })}`;

    document.getElementById('portfolioValue').textContent = fmt(portfolio.total_value);
    document.getElementById('cashAvailable').textContent = fmt(portfolio.cash_balance);
    document.getElementById('openPositions').textContent = `${(portfolio.positions || []).length} / 12`;

    const unrealized = portfolio.unrealized_pnl || 0;
    const unrealizedEl = document.getElementById('unrealizedPnl');
    unrealizedEl.textContent = fmt(unrealized);
    unrealizedEl.className = `stat-value ${unrealized >= 0 ? 'positive' : 'negative'}`;

    const todayPnl = portfolio.today_pnl || 0;
    const todayEl = document.getElementById('todayPnl');
    todayEl.textContent = fmt(todayPnl);
    todayEl.className = `stat-value ${todayPnl >= 0 ? 'positive' : 'negative'}`;

    const utilization = portfolio.capital_limit > 0 ? ((portfolio.deployed_capital / portfolio.capital_limit) * 100).toFixed(0) : 0;
    document.getElementById('capitalUtilization').textContent = `${utilization}%`;
    document.getElementById('capitalProgress').style.width = `${Math.min(utilization, 100)}%`;

    // Positions table
    const positions = portfolio.positions || [];
    const tbody = document.getElementById('positionsBody');
    if (positions.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="empty-row">No open positions</td></tr>';
        return;
    }

    tbody.innerHTML = positions.map(pos => {
        const pnlPct = pos.entry_price > 0 ? (((pos.current_price - pos.entry_price) / pos.entry_price) * 100).toFixed(1) : 0;
        const pnlClass = pnlPct >= 0 ? 'positive' : 'negative';
        const statusClass = pnlPct >= 5 ? 'yes' : pnlPct <= -3 ? 'no' : '';
        const status = pnlPct >= 5 ? 'Near Target' : pnlPct <= -3 ? 'Near SL' : 'Active';

        return `
            <tr>
                <td><strong>${pos.symbol}</strong></td>
                <td>${(pos.entry_price || 0).toFixed(2)}</td>
                <td>${(pos.current_price || 0).toFixed(2)}</td>
                <td class="${pnlClass}">${pnlPct > 0 ? '+' : ''}${pnlPct}%</td>
                <td class="no">${(pos.stop_loss || 0).toFixed(2)}</td>
                <td class="yes">${(pos.target || 0).toFixed(2)}</td>
                <td>${pos.days_held || 0}</td>
                <td class="${statusClass}">${status}</td>
            </tr>
        `;
    }).join('');
}

// ═══════════════════════════════════════════════════════════
// SCANNER TAB
// ═══════════════════════════════════════════════════════════

function renderScanner(candidates) {
    if (!candidates || candidates.length === 0) {
        document.getElementById('scannerBody').innerHTML =
            '<tr><td colspan="8" class="empty-row">Run scanner to populate</td></tr>';
        return;
    }

    // Heatmap
    const heatmap = document.getElementById('heatmap');
    heatmap.innerHTML = candidates.slice(0, 80).map(c => {
        const pct = c.pct_5d || c.pct_change_5d || 0;
        let cls = 'neutral';
        if (pct > 5) cls = 'strong-green';
        else if (pct > 3) cls = 'green';
        else if (pct > 1) cls = 'light-green';
        else if (pct < -5) cls = 'strong-red';
        else if (pct < -3) cls = 'red';
        else if (pct < -1) cls = 'light-red';

        return `<div class="heatmap-cell ${cls}" title="${c.symbol}: ${pct > 0 ? '+' : ''}${pct.toFixed(1)}%">${c.symbol}</div>`;
    }).join('');

    // Table
    const tbody = document.getElementById('scannerBody');
    tbody.innerHTML = candidates.map(c => {
        const pct5 = c.pct_5d || c.pct_change_5d || 0;
        const pct20 = c.pct_20d || c.pct_change_20d || 0;
        const fromHigh = c.near_52w_high || c.from_52w_high || 0;
        const pct5Class = pct5 >= 0 ? 'positive' : 'negative';
        const pct20Class = pct20 >= 0 ? 'positive' : 'negative';

        return `
            <tr>
                <td><strong>${c.symbol}</strong></td>
                <td>${c.score || '—'}</td>
                <td>${(c.last_price || 0).toFixed(2)}</td>
                <td class="${pct5Class}">${pct5 > 0 ? '+' : ''}${pct5.toFixed(1)}%</td>
                <td class="${pct20Class}">${pct20 > 0 ? '+' : ''}${pct20.toFixed(1)}%</td>
                <td>${fromHigh.toFixed(1)}%</td>
                <td>${((c.avg_volume_20d || 0) / 1000000).toFixed(1)}M</td>
                <td>${(c.rationale || []).join(', ') || '—'}</td>
            </tr>
        `;
    }).join('');
}

// ═══════════════════════════════════════════════════════════
// RISK TAB
// ═══════════════════════════════════════════════════════════

function renderRisk(portfolio) {
    if (!portfolio) return;

    const dailyLoss = Math.abs(portfolio.today_pnl || 0);
    const totalValue = portfolio.total_value || 174000;
    const lossPct = (dailyLoss / totalValue * 100).toFixed(2);
    const gauge = document.getElementById('dailyLossGauge');
    const gaugeWidth = Math.min((lossPct / 2) * 100, 100);
    gauge.style.width = `${gaugeWidth}%`;
    gauge.className = `gauge-fill ${lossPct > 1.5 ? 'danger' : lossPct > 1 ? 'warning' : ''}`;
    document.getElementById('dailyLossLabel').textContent = `${lossPct}% / 2% max`;

    // Sector exposure
    const positions = portfolio.positions || [];
    const sectors = {};
    positions.forEach(p => {
        const sector = p.sector || 'Unknown';
        sectors[sector] = (sectors[sector] || 0) + (p.value || 0);
    });

    const sectorBars = document.getElementById('sectorBars');
    if (Object.keys(sectors).length === 0) {
        sectorBars.innerHTML = '<div class="sector-row"><span class="sector-name">No positions</span></div>';
    } else {
        const totalPositionValue = Object.values(sectors).reduce((a, b) => a + b, 0);
        sectorBars.innerHTML = Object.entries(sectors)
            .sort((a, b) => b[1] - a[1])
            .map(([name, value]) => {
                const pct = totalPositionValue > 0 ? ((value / totalPositionValue) * 100).toFixed(0) : 0;
                return `
                    <div class="sector-row">
                        <span class="sector-name">${name}</span>
                        <div class="sector-bar"><div class="sector-fill" style="width: ${pct}%"></div></div>
                        <span class="sector-pct">${pct}%</span>
                    </div>
                `;
            }).join('');
    }
}

// ═══════════════════════════════════════════════════════════
// HISTORY TAB
// ═══════════════════════════════════════════════════════════

function renderHistory(history) {
    if (!history || history.length === 0) {
        document.getElementById('historyBody').innerHTML =
            '<tr><td colspan="9" class="empty-row">No completed trades yet</td></tr>';
        return;
    }

    // Stats
    const wins = history.filter(t => (t.pnl_pct || 0) > 0).length;
    const winRate = ((wins / history.length) * 100).toFixed(0);
    document.getElementById('totalTrades').textContent = history.length;
    document.getElementById('winRate').textContent = `${winRate}%`;

    const avgRR = history.reduce((s, t) => s + (t.rr_achieved || 0), 0) / history.length;
    document.getElementById('avgRR').textContent = avgRR.toFixed(1);

    const totalPnl = history.reduce((s, t) => s + (t.pnl_dkk || 0), 0);
    const totalPnlEl = document.getElementById('totalPnl');
    totalPnlEl.textContent = `Rs.${totalPnl.toLocaleString('en-IN')}`;
    totalPnlEl.className = `stat-value ${totalPnl >= 0 ? 'positive' : 'negative'}`;

    // Table
    const tbody = document.getElementById('historyBody');
    tbody.innerHTML = history.map(t => {
        const pnlClass = (t.pnl_pct || 0) >= 0 ? 'positive' : 'negative';
        const outcome = (t.pnl_pct || 0) > 0 ? '✅ Win' : '❌ Loss';

        return `
            <tr>
                <td>${t.date || '—'}</td>
                <td><strong>${t.symbol}</strong></td>
                <td>${(t.entry_price || 0).toFixed(2)}</td>
                <td>${(t.exit_price || 0).toFixed(2)}</td>
                <td class="${pnlClass}">${(t.pnl_pct || 0) > 0 ? '+' : ''}${(t.pnl_pct || 0).toFixed(1)}%</td>
                <td class="${pnlClass}">${(t.pnl_dkk || 0).toLocaleString('en-IN')}</td>
                <td>${t.days_held || '—'}</td>
                <td>${outcome}</td>
                <td>${t.signal_score || '—'}</td>
            </tr>
        `;
    }).join('');

    // Equity curve
    drawEquityCurve(history);
}

function drawEquityCurve(history) {
    const canvas = document.getElementById('equityCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.parentElement.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // Build cumulative P&L
    let cumulative = portfolio.starting_capital || 100000; // Starting value
    const points = [{ x: 0, y: cumulative }];
    history.forEach((t, i) => {
        cumulative += (t.pnl_dkk || 0);
        points.push({ x: i + 1, y: cumulative });
    });

    if (points.length < 2) return;

    const minY = Math.min(...points.map(p => p.y)) * 0.98;
    const maxY = Math.max(...points.map(p => p.y)) * 1.02;
    const xScale = canvas.width / (points.length - 1);
    const yScale = canvas.height / (maxY - minY);

    // Draw line
    ctx.beginPath();
    ctx.strokeStyle = '#6366f1';
    ctx.lineWidth = 2;
    points.forEach((p, i) => {
        const x = p.x * xScale;
        const y = canvas.height - (p.y - minY) * yScale;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Fill area
    ctx.lineTo(canvas.width, canvas.height);
    ctx.lineTo(0, canvas.height);
    ctx.closePath();
    ctx.fillStyle = 'rgba(99, 102, 241, 0.1)';
    ctx.fill();
}

// ═══════════════════════════════════════════════════════════
// UNIVERSE TAB
