function renderUniverse(universe) {
    if (!universe) {
        // Use hardcoded fallback
        renderUniverseFallback();
        return;
    }

    const tiers = {
        tier1: { el: 'tier1Chips', symbols: universe.tier1_nifty50?.symbols || [] },
        tier2: { el: 'tier2Chips', symbols: universe.tier2_niftynext50?.symbols || [] },
        tier3_dk: { el: 'tier3DkChips', symbols: universe.tier3_defensive?.symbols || [] },
        tier3_eu: { el: 'tier3EuChips', symbols: universe.tier4_momentum?.symbols || [] },
    };

    Object.entries(tiers).forEach(([key, { el, symbols }]) => {
        const container = document.getElementById(el);
        if (container) {
            container.innerHTML = symbols.map(s => `<span class="chip">${s}</span>`).join('');
        }
    });
}

