// ═══════════════════════════════════════════════════════════
// MARKET STATUS
// ═══════════════════════════════════════════════════════════

function updateMarketStatus() {
    const now = new Date();
    const utcH = now.getUTCHours(), utcM = now.getUTCMinutes();
    const istTotalMin = utcH * 60 + utcM + 330; // IST = UTC + 5:30
    const istH = Math.floor(istTotalMin / 60) % 24;
    const istM = istTotalMin % 60;
    const day = now.getUTCDay();
    const el = document.getElementById('marketStatus');

    if (day === 0 || day === 6) {
        el.textContent = '\u25cf NSE Closed (Weekend)';
        el.className = 'market-status';
        return;
    }

    const istMinutes = istH * 60 + istM;
    // NSE: Pre-market 9:00-9:15, Open 9:15-15:30
    if (istMinutes >= 555 && istMinutes <= 930) {
        el.textContent = '\u25cf NSE Open';
        el.className = 'market-status open';
    } else if (istMinutes >= 540 && istMinutes < 555) {
        el.textContent = '\u25cf Pre-Market';
        el.className = 'market-status';
    } else {
        el.textContent = '\u25cf NSE Closed';
        el.className = 'market-status';
    }
}

// ═══════════════════════════════════════════════════════════
// INITIALIZATION
// ═══════════════════════════════════════════════════════════

async function loadAllData() {
    const [signals, candidates, portfolio, history, universe] = await Promise.all([
        loadJSON('signals.json'),
        loadJSON('candidates.json'),
        loadJSON('portfolio.json'),
        loadJSON('history.json'),
        loadJSON('universe.json'),
    ]);

    window._currentSignals = signals || [];

    renderSignals(signals);
    renderScanner(candidates);
    renderPortfolio(portfolio);
    renderRisk(portfolio);
    renderHistory(history);
    renderUniverse(universe);

    // Update timestamp
    document.getElementById('lastUpdate').textContent =
        `Updated: ${new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`;

    if (signals && signals.length > 0) {
        const today = new Date().toISOString().split('T')[0];
        document.getElementById('signalDate').textContent = today;
    }
}

// Event listeners
document.addEventListener('DOMContentLoaded', () => {
    initTabs();
    updateMarketStatus();
    setInterval(updateMarketStatus, 60000);
    loadAllData();
    renderUniverseFallback(); // Always show universe even without data file

    // Refresh button
    document.getElementById('btnRefresh').addEventListener('click', loadAllData);

    // Close rationale panel
    document.getElementById('closeRationale').addEventListener('click', () => {
        document.getElementById('rationalePanel').style.display = 'none';
    });

    // Scanner search
    document.getElementById('scannerSearch')?.addEventListener('input', (e) => {
        const query = e.target.value.toLowerCase();
        const rows = document.querySelectorAll('#scannerBody tr');
        rows.forEach(row => {
            const symbol = row.querySelector('td')?.textContent?.toLowerCase() || '';
            row.style.display = symbol.includes(query) ? '' : 'none';
        });
    });
});
